import { Column, CreateDateColumn, Entity, Index, PrimaryColumn } from 'typeorm';

export const DOCUMENT_KINDS = [
  'id_front',
  'id_back',
  'proof_of_address',
  'cac_certificate',
] as const;
export type DocumentKind = (typeof DOCUMENT_KINDS)[number];

/** Metadata for a file held (encrypted) in private object storage. The file itself is only served through the API. */
@Entity('documents')
export class Document {
  /** Generated by the server before upload; also the encryption context for this file. */
  @PrimaryColumn('uuid')
  id: string;

  @Index()
  @Column({ type: 'uuid' })
  ownerUserId: string;

  @Column({ type: 'varchar', length: 30 })
  kind: string;

  /** Detected from the file's own bytes, never trusted from the client. */
  @Column({ type: 'varchar', length: 40 })
  mime: string;

  @Column({ type: 'integer' })
  size: number;

  @Column({ type: 'varchar', length: 64 })
  sha256: string;

  @Column({ type: 'varchar', length: 120 })
  objectKey: string;

  @Column({ type: 'varchar', length: 120 })
  storageFileId: string;

  @CreateDateColumn({ type: 'timestamptz' })
  createdAt: Date;

  @Column({ type: 'timestamptz', nullable: true })
  deletedAt: Date | null;
}
